    processSequence : ARRAY[1..8] OF USINT;
END_VAR
VAR_OUTPUT
    conveyorLeft : BOOL;
    conveyorRight : BOOL;
END_VAR
VAR
    idx : USINT := 1;
    currentStation : USINT := 1;
    targetStation : USINT := 0;
    prevStation1Start : BOOL := FALSE;
    prevComplete2 : BOOL := FALSE;
    prevComplete3 : BOOL := FALSE;
    prevComplete4 : BOOL := FALSE;
END_VAR

// Power-up validation
IF processLength < 1 OR processLength > 8 THEN
    conveyorLeft := FALSE;
    conveyorRight := FALSE;
    RETURN;
END_IF;

// Rising edge detection
startRising := station1Start AND NOT prevStation1Start;
completeRising := (station2Complete AND NOT prevComplete2) OR
                  (station3Complete AND NOT prevComplete3) OR
                  (station4Complete AND NOT prevComplete4);

// Start condition
IF targetStation = 0 AND startRising THEN
    targetStation := processSequence[1];
    idx := 2;
END_IF

// Waiting for completion, advance on rising edge
IF targetStation = 0 AND completeRising THEN
    IF idx <= processLength THEN
        targetStation := processSequence[idx];
        idx := idx + 1;
    END_IF
END_IF

// Update current station from sensors
IF sensor1 THEN currentStation := 1; END_IF
IF sensor2 THEN currentStation := 2; END_IF
IF sensor3 THEN currentStation := 3; END_IF
IF sensor4 THEN currentStation := 4; END_IF
IF sensor5 THEN currentStation := 5; END_IF

// Target reached, wait for completion
IF targetStation > 0 AND currentStation = targetStation THEN
    targetStation := 0;
END_IF

// Conveyor control
IF targetStation > currentStation THEN
    conveyorRight := TRUE;
    conveyorLeft := FALSE;
ELSIF targetStation < currentStation THEN
    conveyorLeft := TRUE;
    conveyorRight := FALSE;
ELSE
    conveyorLeft := FALSE;
    conveyorRight := FALSE;
END_IF

// Update edge detection history
prevStation1Start := station1Start;
prevComplete2 := station2Complete;
prevComplete3 := station3Complete;
prevComplete4 := station4Complete;
```

